self.KB_CONTENT["card:753367"]={"id":"card:753367","ty":"card","sourceId":"753367","title":"『產能資料建立作業』中的『有效機時 (MZ005)』為何？","ver":"iGP","topic":"大於","keywords":["大於","等於"],"y":"other","answer":"* 有效機時=機器產能×負荷率。* 此欄位必須大於等於零。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
