self.KB_CONTENT["card:792683"]={"id":"card:792683","ty":"card","sourceId":"792683","title":"『產品成本分析表』中的『選擇年月 (ME002)』為何？","ver":"GP4以上","topic":"分析表","keywords":["分析表","庫存","產品","年月"],"y":"other","answer":"* 起迄年月預設為庫存現行年月，亦可修改，空白表全部。進階選項","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
